Method.Implementation:
	set daObj = ##class(%DynamicObject).%New()

	$$$TRACE( "-START- ParseAllNodes: NodeData="_node.NodeData _ ", Parent? " _ first)
	set prevNode = ""
	set dcObj = ""
	set arrInd = 1
	set eleArrInd = 1
	DO
	 {
		 set stat = $$$OK
		// Remove While elements
		while ((stat) && (node.NodeType = $$$xmlWHITESPACENODE))
    	{
	    	set stat = node.MoveToNextSibling()
    	}
    	if (stat)
    	{
			$$$TRACE( " -- Sibling Node= "_node.NodeData _ ", Parent: " _ parentNode _ " NodeType="_node.NodeType_" QName="_node.QName_" HasChildNodes returns "_node.HasChildNodes()_" GetNumberAttributes returns "_node.GetNumberAttributes())

			 Set count=node.GetNumberAttributes()
			 if (count >= 1)
			 {

			    $$$TRACE( " --- NodeData="_node.NodeData _ "_ Number of attributes: "_ count)
			    Set next=node.FirstAttributeName()

			    For i=1:1:count {
				    set val = node.GetAttributeValue(next)
			        $$$TRACE( "  -- Attribute " _ i _ ". "_ next _ "_ value is: "_ val)
			        set attrArray("@"_next) = val
			        Set next=node.NextAttributeName(next)
			    }
			}
	        if (node.NodeType = $$$xmlELEMENTNODE)
	        {
		        set text = ""
		    	Set status=node.GetText(.text)
		    	If status {
		        	$$$TRACE( "  -- ParseAllNodes:xmlELEMENTNODE: " _ node.NodeData _ ", text of the node is "_text)	        
		        	// $$$TRACE( node.NodeData _ ", text of the node is "_text
		        	// Do daObj.%Set(, text)
		    	}
	        }
	        if (node.HasChildNodes())
		    {
			    set callParseNode = 0
			    Do node.MoveToFirstChild()

				if ( (node.NodeType = $$$xmlELEMENTNODE) || (first = 1))
				{
					set callParseNode = 1
				}
				Do node.MoveToParent()
				if (callParseNode = 1)
				{
			    	// $$$TRACE( "Call ParseChildNode" _ node

		    		set dcObj = ..ParseChildNode(parentNode, node, first, listArr )
		    		// $$$TRACE( "   =From ParseChildNode= Node: " _ node.NodeData _ ", " _ dcObj)
				}
				else
				{
					set dcObj = text
				}

		    }
		    else
		    {
			    set dcObj = ""
		    }
		    $$$TRACE( "Check in the inbound List = " _ node.NodeData)
		    if ($LISTFIND(listArr, node.NodeData) >= 1)
		    {
			    // Calling function sent names of nodes that should be created as ARRAY
			    $$$TRACE( "  === CREATE ARRAY: " _ node.NodeData _ " Found in List, Index: " _ $LISTFIND(listArr, node.NodeData))
			    $$$TRACE( $Query(^||arrList("")))

			    if ($$$IsdefObject(dcObj))
			    {
			    	$$$TRACE( "arrList: " _ arrInd _ ", " _ dcObj.%ToJSON())
			    	set ^||arrList(parentNode, node.NodeData, arrInd) = dcObj.%ToJSON()
			    }
			    else
			    {
				    $$$TRACE( "arrList: " _ arrInd _ ", " _ dcObj)
			    	set ^||arrList(parentNode, node.NodeData, arrInd) = dcObj
			    }
			    set arrInd = arrInd + 1

			    // --- Add Duplicate array ---
			    set key = $Query(^||arrList(""))
			    if (key '= "") {
			   		set newDynArr = ##class(%DynamicArray).%New()
			   		While (key '= "") {
				   		set delInd = 1
	  				   // Write out contents
	     				$$$TRACE( "arrList array #" _ key _ ", " _ @key)
	     				if ((key [ parentNode) && (key [ node.NodeData))
	     				{
		     				set obj = @key
		     				SET delArr(delInd) = key
		     				set delInd = delInd + 1
		     				try
		     				{
			     				$$$TRACE( "Try to add object: " _ obj)
		     					set multiObj = {}.%FromJSON(obj)

		     					Do newDynArr.%Push(multiObj)
		     				} catch exp
		     				{
			     				$$$TRACE("Add String " _ obj)
			     				Do newDynArr.%Push(obj)
		     				}
	     				}

	     				// Find next node
	     				Set key = $Query(@key)
	 				}

			   		Do daObj.%Set(node.NodeData, newDynArr)

			   		SET key=$ORDER(delArr(""))
				    WHILE (key'="") {
				      kill ^||arrList(delArr(key))
				      $$$TRACE("Delete key: " _  delArr(key))
				      SET key = $ORDER(delArr(key))
				   }
			    }

		   		// -- Check Element array
		   		set key = $Query(^||eleArrList(""))
		   		if (key '= "") {
			   		set newDynArr = ##class(%DynamicArray).%New()

			   		While (key '= "") {
	  				   // Write out contents
	     				$$$TRACE(  "eleArrList - node.NodeData: " _ node.NodeData _ ", array #" _ key _ ", " _ @key)
	     				if ((key [ "element") && (key [ node.NodeData))
	     				{
		     				set obj = @key

		     				try
		     				{
			     				$$$TRACE(  "Try to add object: " _ obj)
		     					set multiObj = {}.%FromJSON(obj)

		     					Do newDynArr.%Push(multiObj)
		     				} catch exp
		     				{
			     				$$$TRACE( "Add String " _ obj)
			     				Do newDynArr.%Push(obj)
		     				}
	     				}

	     				// Find next node
	     				Set key = $Query(@key)
	 				}

			   		Do daObj.%Set(node.NodeData, newDynArr)

				      kill ^||eleArrList

		   		}
		    }
		    elseif ( ($LISTFIND(listArr, parentNode) >= 1)  &&(node.NodeData = "element"))
			{
		         $$$TRACE( "  === CREATE ARRAY for parent: " _ parentNode _ ", element name: " _ node.NodeData)

			    if ($$$IsdefObject(dcObj))
			    {
			    	$$$TRACE(  " eleArrList: " _ parentNode _" arrList: " _ eleArrInd _ ", " _ dcObj.%ToJSON())
			    	set ^||eleArrList(parentNode, node.NodeData, eleArrInd) = dcObj.%ToJSON()
			    }
			    else
			    {
				    $$$TRACE(  " eleArrList: " _ parentNode _ " arrList: " _ eleArrInd _ ", " _ dcObj)
			    	set ^||eleArrList(parentNode, node.NodeData, eleArrInd) = dcObj
			    }
			    set eleArrInd = eleArrInd + 1
		    }

		    else
		    {
			    $$$TRACE( "  -- SET New node, not in LIST " _ node.NodeData )
			    Do daObj.%Set(node.NodeData, dcObj)


 				set key = $ORDER(attrArray(""))
   				while (key '= "") 
   				{ 
   					$$$TRACE( "Add Attribute element:"_key_"=/"_attrArray(key))
   					Do dcObj.%Set(key, attrArray(key))
   					set key = $ORDER(attrArray(key))
   				}

			    kill attrArray

		    }



		    set prevNode = node.NodeData
    	}
	 } WHILE (node.MoveToNextSibling())
	 $$$TRACE( " $END$ ParseAllNodes: " _ daObj.%ToJSON())

	Quit daObj


	// $$$TRACE( "ParseChildNode: " _node.NodeData  
	$$$TRACE( "   -START- ParseChildNode: NodeData="_node.NodeData)
	set parentNode = node.NodeData
    set stat = node.MoveToFirstChild()

	$$$TRACE("   ---  Child NODE: NodeData="_node.NodeData_" NodeId="_node.NodeId_ ", Parent: " _ parentNode)
	$$$TRACE("    ---- NodeType="_node.NodeType_" QName="_node.QName_" HasChildNodes returns "_node.HasChildNodes()_" GetNumberAttributes returns "_node.GetNumberAttributes())

	while(node.NodeType = $$$xmlWHITESPACENODE)
    {
	    set stat = node.MoveToNextSibling()
    }

	if (node.NodeType = $$$xmlELEMENTNODE)
    {

		set dcObj = ..ParseAllNodes(parentNode, node, 0, listArr)
		$$$TRACE( "   *** ParseChildNode: -- from ParseAllNodes: " _ node.NodeData _ " , " _ dcObj.%ToJSON())

    }
    else
    {
	    // xmlTEXTNODE

	    set dcObj = node.NodeData

    }
	Do node.MoveToParent()
	$$$TRACE( "   $END$ ParseChildNode Output: " _ dcObj _ ", Parent NodeData="_node.NodeData)
	Quit dcObj
